-- Seed data: sample sentence prompts (3 per category = 60), published.
-- Safe to re-run: a row is skipped when the same sentence already exists for that level and category.
-- Run in the Supabase SQL editor after migrations 0003, 0004 and 0008 (the last part fills prompt_answers).

insert into public.prompts (writing_type, title, prompt_text, hint, difficulty, category, is_published)
select 'sentence'::public.writing_type, left(v.vietnamese, 80), v.vietnamese, v.hint, v.level, v.category, true
from (values
  ('beginner', 'personal-communication', 'Tôi muốn giới thiệu bạn của tôi.', 'introduce, friend'),
  ('intermediate', 'personal-communication', 'Bạn có thể gửi lại tin nhắn cho tôi trước buổi tối được không?', 'resend, message, before evening'),
  ('advanced', 'personal-communication', 'Dù đã giải thích nhiều lần, anh ấy vẫn hiểu sai ý của tôi.', 'despite, explain, misunderstand, intention'),
  ('beginner', 'everyday-life', 'Sáng nào tôi cũng dậy lúc sáu giờ.', 'wake up, every morning'),
  ('intermediate', 'everyday-life', 'Tôi thường dành cuối tuần để dọn dẹp nhà cửa và nấu ăn cho cả tuần.', 'spend, tidy up, meals for the week'),
  ('advanced', 'everyday-life', 'Giữ một thói quen đều đặn khó hơn nhiều so với việc bắt đầu nó.', 'maintain, routine, consistent'),
  ('beginner', 'transportation-travel', 'Xe buýt đến trạm lúc tám giờ.', 'bus, stop, arrive'),
  ('intermediate', 'transportation-travel', 'Chuyến bay của chúng tôi bị hoãn vì thời tiết xấu.', 'flight, delay, bad weather'),
  ('advanced', 'transportation-travel', 'Nếu tôi biết trước đường sẽ kẹt như vậy, tôi đã đi tàu điện ngầm.', 'if I had known, traffic jam, subway'),
  ('beginner', 'school-education', 'Em gái tôi học lớp năm.', 'younger sister, fifth grade'),
  ('intermediate', 'school-education', 'Giáo viên yêu cầu chúng tôi nộp bài tập vào thứ Sáu.', 'teacher, require, submit, assignment'),
  ('advanced', 'school-education', 'Giáo dục không chỉ truyền đạt kiến thức mà còn rèn luyện tư duy phản biện.', 'not only, but also, convey, critical thinking'),
  ('beginner', 'work-business', 'Chị ấy làm việc trong một công ty nhỏ.', 'work, company'),
  ('intermediate', 'work-business', 'Chúng tôi cần hoàn thành báo cáo trước cuộc họp vào sáng mai.', 'finish, report, meeting'),
  ('advanced', 'work-business', 'Công ty đang cân nhắc mở rộng thị trường để giảm sự phụ thuộc vào một khách hàng.', 'consider, expand, market, reduce dependence'),
  ('beginner', 'public-services', 'Thư viện mở cửa lúc chín giờ.', 'library, open'),
  ('intermediate', 'public-services', 'Tôi phải xếp hàng hai tiếng để làm giấy tờ ở phường.', 'queue, paperwork, local office'),
  ('advanced', 'public-services', 'Dịch vụ công trực tuyến giúp người dân tiết kiệm thời gian, nhưng cần đảm bảo ai cũng tiếp cận được.', 'online public services, ensure, access, citizens'),
  ('beginner', 'health-medicine', 'Tôi bị đau đầu.', 'have a headache'),
  ('intermediate', 'health-medicine', 'Bác sĩ khuyên tôi nên ngủ đủ giấc và uống nhiều nước.', 'advise, enough sleep, plenty of water'),
  ('advanced', 'health-medicine', 'Phòng bệnh luôn hiệu quả hơn và rẻ hơn so với chữa bệnh.', 'prevention, effective, treatment'),
  ('beginner', 'shopping-money', 'Cái áo này giá bao nhiêu?', 'how much, shirt'),
  ('intermediate', 'shopping-money', 'Tôi đang cố tiết kiệm tiền để mua một chiếc laptop mới.', 'save money, laptop'),
  ('advanced', 'shopping-money', 'Nhiều người tiêu dùng bị thuyết phục mua những thứ họ thật sự không cần.', 'consumers, persuaded, actually need'),
  ('beginner', 'food-drink', 'Tôi thích ăn phở vào bữa sáng.', 'like, pho, breakfast'),
  ('intermediate', 'food-drink', 'Món canh này hơi mặn, bạn có thể thêm chút nước không?', 'soup, salty, add water'),
  ('advanced', 'food-drink', 'Ẩm thực địa phương phản ánh lịch sử và khí hậu của cả một vùng.', 'cuisine, reflect, climate, region'),
  ('beginner', 'entertainment-leisure', 'Chúng tôi xem phim vào tối thứ Bảy.', 'watch a movie, Saturday evening'),
  ('intermediate', 'entertainment-leisure', 'Cuối tuần này bạn có muốn đi xem hòa nhạc với tôi không?', 'concert, this weekend, would you like'),
  ('advanced', 'entertainment-leisure', 'Thời gian rảnh được dùng tốt có thể giúp con người hồi phục và sáng tạo hơn.', 'leisure time, recover, creative'),
  ('beginner', 'nature-environment', 'Hôm nay trời nắng và đẹp.', 'sunny, beautiful'),
  ('intermediate', 'nature-environment', 'Chúng ta nên giảm rác thải nhựa để bảo vệ biển.', 'reduce, plastic waste, protect, ocean'),
  ('advanced', 'nature-environment', 'Biến đổi khí hậu đang đe dọa nhiều loài động vật đến mức tuyệt chủng.', 'climate change, threaten, species, extinction'),
  ('beginner', 'science-technology', 'Điện thoại của tôi hết pin.', 'phone, battery, run out'),
  ('intermediate', 'science-technology', 'Trí tuệ nhân tạo đang thay đổi cách chúng ta làm việc.', 'artificial intelligence, change, the way'),
  ('advanced', 'science-technology', 'Tiến bộ công nghệ chỉ thật sự có ích khi nó đi kèm trách nhiệm đạo đức.', 'technological progress, beneficial, ethical responsibility'),
  ('beginner', 'culture-society', 'Tết là ngày lễ quan trọng nhất ở Việt Nam.', 'Tet, holiday, important'),
  ('intermediate', 'culture-society', 'Ở nước tôi, người trẻ thường sống chung với cha mẹ cho đến khi lập gia đình.', 'young people, live with parents, get married'),
  ('advanced', 'culture-society', 'Sự khác biệt giữa các thế hệ có thể là nguồn xung đột, nhưng cũng là cơ hội để học hỏi.', 'generational differences, conflict, opportunity'),
  ('beginner', 'government-politics', 'Thị trưởng sống ở thành phố này.', 'mayor, city'),
  ('intermediate', 'government-politics', 'Công dân từ mười tám tuổi trở lên có quyền bỏ phiếu.', 'citizens, aged eighteen, right to vote'),
  ('advanced', 'government-politics', 'Một chính phủ minh bạch dễ nhận được sự tin tưởng của người dân hơn.', 'transparent, government, public trust'),
  ('beginner', 'history-geography', 'Hà Nội là thủ đô của Việt Nam.', 'capital'),
  ('intermediate', 'history-geography', 'Sông Mê Kông chảy qua nhiều quốc gia trước khi ra biển.', 'Mekong River, flow through, countries, reach the sea'),
  ('advanced', 'history-geography', 'Hiểu lịch sử giúp chúng ta tránh lặp lại những sai lầm của quá khứ.', 'understanding history, avoid repeating, mistakes'),
  ('beginner', 'sports-fitness', 'Tôi chạy bộ mỗi buổi sáng.', 'jog, every morning'),
  ('intermediate', 'sports-fitness', 'Đội của chúng tôi đã thắng trận đấu sau một hiệp phụ căng thẳng.', 'team, win, match, extra time, tense'),
  ('advanced', 'sports-fitness', 'Tập thể dục đều đặn không chỉ rèn luyện cơ thể mà còn cải thiện tinh thần.', 'regular exercise, improve, mental health'),
  ('beginner', 'arts-literature', 'Tôi thích đọc truyện ngắn.', 'short stories'),
  ('intermediate', 'arts-literature', 'Bức tranh này làm tôi nhớ về tuổi thơ ở quê.', 'painting, remind, childhood, hometown'),
  ('advanced', 'arts-literature', 'Một tác phẩm hay không đưa ra câu trả lời mà khiến người đọc đặt ra câu hỏi.', 'work of art, provide answers, raise questions'),
  ('beginner', 'religion-spirituality', 'Gia đình tôi đi chùa vào ngày rằm.', 'temple, full moon day'),
  ('intermediate', 'religion-spirituality', 'Nhiều người tìm đến thiền để giảm căng thẳng và tìm sự bình yên.', 'meditation, reduce stress, inner peace'),
  ('advanced', 'religion-spirituality', 'Tôn trọng tín ngưỡng của người khác là nền tảng của một xã hội hòa hợp.', 'respect, beliefs, foundation, harmonious society'),
  ('beginner', 'law-justice', 'Chúng ta phải tuân theo luật.', 'obey, law'),
  ('intermediate', 'law-justice', 'Người lái xe phải có bằng lái và bảo hiểm hợp lệ.', 'driver, license, valid insurance'),
  ('advanced', 'law-justice', 'Mọi người đều bình đẳng trước pháp luật, bất kể địa vị hay tài sản.', 'equal before the law, regardless of, status, wealth'),
  ('beginner', 'philosophy-ethics', 'Nói thật là việc tốt.', 'telling the truth, good'),
  ('intermediate', 'philosophy-ethics', 'Có lúc chúng ta phải chọn giữa điều đúng và điều dễ dàng.', 'choose between, right, easy'),
  ('advanced', 'philosophy-ethics', 'Liệu một hành động có thể được coi là đạo đức nếu nó chỉ xuất phát từ nỗi sợ bị trừng phạt?', 'moral, stem from, fear of punishment')
) as v(level, category, vietnamese, hint)
where not exists (
  select 1 from public.prompts p
  where p.writing_type = 'sentence' and p.difficulty = v.level and p.category = v.category and p.prompt_text = v.vietnamese
);


-- Accepted answers with grammar notes for the sentences above (2 per sentence).
-- Needs migration 0008_accepted_answers.sql. Safe to re-run: a prompt that already has answers keeps them,
-- so anything an admin edited is never overwritten.
insert into public.prompt_answers (prompt_id, answers)
select p.id, v.answers
from (values
  ('beginner', 'personal-communication', 'Tôi muốn giới thiệu bạn của tôi.', $j$[{"text": "I want to introduce my friend.", "structureVi": "want to + V: muốn làm gì\nintroduce + người: giới thiệu ai", "structureEn": "want to + verb: express a wish\nintroduce + person"}, {"text": "I would like to introduce my friend.", "structureVi": "would like to + V: cách nói lịch sự hơn want to", "structureEn": "would like to + verb: a more polite way to say want to"}]$j$::jsonb),
  ('intermediate', 'personal-communication', 'Bạn có thể gửi lại tin nhắn cho tôi trước buổi tối được không?', $j$[{"text": "Could you resend me the message before this evening?", "structureVi": "Could you + V?: lời đề nghị lịch sự\nbefore + mốc thời gian", "structureEn": "Could you + verb?: a polite request\nbefore + time"}, {"text": "Can you send me the message again before the evening?", "structureVi": "Can you + V?: nhờ ai làm gì\nsend + ai + cái gì", "structureEn": "Can you + verb?: ask someone to do something\nsend + person + thing"}]$j$::jsonb),
  ('advanced', 'personal-communication', 'Dù đã giải thích nhiều lần, anh ấy vẫn hiểu sai ý của tôi.', $j$[{"text": "Despite explaining it many times, he still misunderstands what I mean.", "structureVi": "Despite + V-ing: mặc dù đã làm gì\nstill + V: vẫn còn", "structureEn": "Despite + V-ing: even though something happened\nstill + verb"}, {"text": "Although I have explained it many times, he still misunderstands me.", "structureVi": "Although + mệnh đề: mặc dù\nthì hiện tại hoàn thành: have explained", "structureEn": "Although + clause: even though\npresent perfect: have explained"}]$j$::jsonb),
  ('beginner', 'everyday-life', 'Sáng nào tôi cũng dậy lúc sáu giờ.', $j$[{"text": "I wake up at six o'clock every morning.", "structureVi": "every morning: thói quen hằng ngày, dùng thì hiện tại đơn\nat + giờ", "structureEn": "every morning: a daily habit, present simple\nat + time"}, {"text": "Every morning, I get up at six.", "structureVi": "get up = wake up: thức dậy\ntrạng từ chỉ tần suất đứng đầu câu", "structureEn": "get up = wake up\na frequency phrase can start the sentence"}]$j$::jsonb),
  ('intermediate', 'everyday-life', 'Tôi thường dành cuối tuần để dọn dẹp nhà cửa và nấu ăn cho cả tuần.', $j$[{"text": "I usually spend my weekends cleaning the house and cooking for the whole week.", "structureVi": "spend + thời gian + V-ing: dành thời gian làm gì\nusually: trạng từ tần suất", "structureEn": "spend + time + V-ing\nusually: a frequency adverb"}, {"text": "I usually spend the weekend tidying up and preparing meals for the week.", "structureVi": "tidy up: dọn dẹp\nprepare meals for + khoảng thời gian", "structureEn": "tidy up = clean\nprepare meals for + a period of time"}]$j$::jsonb),
  ('advanced', 'everyday-life', 'Giữ một thói quen đều đặn khó hơn nhiều so với việc bắt đầu nó.', $j$[{"text": "Maintaining a regular habit is much harder than starting one.", "structureVi": "Danh động từ làm chủ ngữ: Maintaining...\nso sánh hơn: much harder than", "structureEn": "A gerund as the subject: Maintaining...\ncomparative: much harder than"}, {"text": "It is much harder to keep a consistent routine than to start one.", "structureVi": "It is + adj + to V: thật khó để làm gì\nthan to + V: so sánh hai hành động", "structureEn": "It is + adjective + to + verb\nthan to + verb: compares two actions"}]$j$::jsonb),
  ('beginner', 'transportation-travel', 'Xe buýt đến trạm lúc tám giờ.', $j$[{"text": "The bus arrives at the stop at eight o'clock.", "structureVi": "arrive at + địa điểm nhỏ: đến một trạm\nthì hiện tại đơn cho lịch trình", "structureEn": "arrive at + a small place\npresent simple for schedules"}, {"text": "The bus gets to the bus stop at eight.", "structureVi": "get to = arrive at\nat + giờ", "structureEn": "get to = arrive at\nat + time"}]$j$::jsonb),
  ('intermediate', 'transportation-travel', 'Chuyến bay của chúng tôi bị hoãn vì thời tiết xấu.', $j$[{"text": "Our flight was delayed because of bad weather.", "structureVi": "Câu bị động quá khứ: was delayed\nbecause of + danh từ", "structureEn": "Past passive: was delayed\nbecause of + noun"}, {"text": "Our flight was postponed due to bad weather.", "structureVi": "postpone/delay: hoãn lại\ndue to + danh từ = because of", "structureEn": "postpone/delay\ndue to + noun = because of"}]$j$::jsonb),
  ('advanced', 'transportation-travel', 'Nếu tôi biết trước đường sẽ kẹt như vậy, tôi đã đi tàu điện ngầm.', $j$[{"text": "If I had known the traffic would be that bad, I would have taken the subway.", "structureVi": "Câu điều kiện loại 3: If + had + V3, would have + V3\ndiễn tả điều không có thật ở quá khứ", "structureEn": "Third conditional: If + had + past participle, would have + past participle\nan unreal past situation"}, {"text": "Had I known the road would be so jammed, I would have taken the metro.", "structureVi": "Đảo ngữ điều kiện loại 3: Had + S + V3\nbỏ If", "structureEn": "Inverted third conditional: Had + subject + past participle\nIf is dropped"}]$j$::jsonb),
  ('beginner', 'school-education', 'Em gái tôi học lớp năm.', $j$[{"text": "My younger sister is in fifth grade.", "structureVi": "be in + lớp: đang học lớp mấy\nyounger sister: em gái", "structureEn": "be in + grade\nyounger sister"}, {"text": "My little sister studies in the fifth grade.", "structureVi": "study in + lớp\nlittle sister = em gái", "structureEn": "study in + grade\nlittle sister = younger sister"}]$j$::jsonb),
  ('intermediate', 'school-education', 'Giáo viên yêu cầu chúng tôi nộp bài tập vào thứ Sáu.', $j$[{"text": "The teacher asked us to hand in our homework on Friday.", "structureVi": "ask + ai + to V: yêu cầu ai làm gì\non + thứ trong tuần", "structureEn": "ask + person + to + verb\non + day of the week"}, {"text": "Our teacher requires us to submit the assignment by Friday.", "structureVi": "require + ai + to V\nby + mốc thời gian: chậm nhất là", "structureEn": "require + person + to + verb\nby + time: no later than"}]$j$::jsonb),
  ('advanced', 'school-education', 'Giáo dục không chỉ truyền đạt kiến thức mà còn rèn luyện tư duy phản biện.', $j$[{"text": "Education not only conveys knowledge but also trains critical thinking.", "structureVi": "not only... but also...: không chỉ... mà còn...\nconvey: truyền đạt", "structureEn": "not only... but also...\nconvey = pass on"}, {"text": "Education does not just pass on knowledge, it also develops critical thinking.", "structureVi": "not just... also...: cách nói tự nhiên hơn\ndevelop: rèn luyện, phát triển", "structureEn": "not just... also... : a more natural form\ndevelop = build up"}]$j$::jsonb),
  ('beginner', 'work-business', 'Chị ấy làm việc trong một công ty nhỏ.', $j$[{"text": "She works at a small company.", "structureVi": "work at + công ty: làm việc tại\nshe + V-s: thì hiện tại đơn", "structureEn": "work at + company\nshe + verb-s: present simple"}, {"text": "She works for a small company.", "structureVi": "work for + công ty: làm cho công ty\na small company: một công ty nhỏ", "structureEn": "work for + company\na small company"}]$j$::jsonb),
  ('intermediate', 'work-business', 'Chúng tôi cần hoàn thành báo cáo trước cuộc họp vào sáng mai.', $j$[{"text": "We need to finish the report before the meeting tomorrow morning.", "structureVi": "need to + V: cần phải làm gì\nbefore + sự kiện", "structureEn": "need to + verb\nbefore + event"}, {"text": "We have to complete the report before tomorrow morning's meeting.", "structureVi": "have to + V: bắt buộc phải\nsở hữu cách: tomorrow morning's meeting", "structureEn": "have to + verb: must\npossessive: tomorrow morning's meeting"}]$j$::jsonb),
  ('advanced', 'work-business', 'Công ty đang cân nhắc mở rộng thị trường để giảm sự phụ thuộc vào một khách hàng.', $j$[{"text": "The company is considering expanding its market to reduce its dependence on a single customer.", "structureVi": "consider + V-ing: cân nhắc làm gì\nto V chỉ mục đích: to reduce\ndependence on", "structureEn": "consider + V-ing\nto + verb for purpose: to reduce\ndependence on"}, {"text": "The company is thinking about expanding into new markets in order to depend less on one client.", "structureVi": "think about + V-ing\nin order to + V: để\ndepend on: phụ thuộc vào", "structureEn": "think about + V-ing\nin order to + verb\ndepend on"}]$j$::jsonb),
  ('beginner', 'public-services', 'Thư viện mở cửa lúc chín giờ.', $j$[{"text": "The library opens at nine o'clock.", "structureVi": "open at + giờ: mở cửa lúc\nthì hiện tại đơn cho giờ mở cửa", "structureEn": "open at + time\npresent simple for opening hours"}, {"text": "The library is open from nine o'clock.", "structureVi": "be open from + giờ: mở cửa từ\ntính từ open", "structureEn": "be open from + time\nthe adjective open"}]$j$::jsonb),
  ('intermediate', 'public-services', 'Tôi phải xếp hàng hai tiếng để làm giấy tờ ở phường.', $j$[{"text": "I had to queue for two hours to get my documents done at the local office.", "structureVi": "had to + V: đã phải làm gì\nqueue for + thời gian\nto V chỉ mục đích", "structureEn": "had to + verb\nqueue for + duration\nto + verb for purpose"}, {"text": "I had to wait in line for two hours to do my paperwork at the ward office.", "structureVi": "wait in line = queue\npaperwork: giấy tờ (không đếm được)", "structureEn": "wait in line = queue\npaperwork is uncountable"}]$j$::jsonb),
  ('advanced', 'public-services', 'Dịch vụ công trực tuyến giúp người dân tiết kiệm thời gian, nhưng cần đảm bảo ai cũng tiếp cận được.', $j$[{"text": "Online public services save citizens time, but we must make sure everyone can access them.", "structureVi": "make sure + mệnh đề: bảo đảm rằng\neveryone + V số ít\naccess: tiếp cận", "structureEn": "make sure + clause\neveryone + singular verb\naccess"}, {"text": "Online government services help people save time, but it is important to ensure that everyone has access.", "structureVi": "help + ai + V: giúp ai làm gì\nIt is important to + V\nhave access to", "structureEn": "help + person + verb\nIt is important to + verb\nhave access to"}]$j$::jsonb),
  ('beginner', 'health-medicine', 'Tôi bị đau đầu.', $j$[{"text": "I have a headache.", "structureVi": "have a + bệnh/triệu chứng: bị đau gì\nheadache: đau đầu", "structureEn": "have a + symptom\nheadache"}, {"text": "My head hurts.", "structureVi": "hurt: đau (nội động từ)\nmy head: đầu của tôi", "structureEn": "hurt: to feel pain\nmy head"}]$j$::jsonb),
  ('intermediate', 'health-medicine', 'Bác sĩ khuyên tôi nên ngủ đủ giấc và uống nhiều nước.', $j$[{"text": "The doctor advised me to get enough sleep and drink plenty of water.", "structureVi": "advise + ai + to V: khuyên ai làm gì\nenough + danh từ\nplenty of + danh từ không đếm được", "structureEn": "advise + person + to + verb\nenough + noun\nplenty of + uncountable noun"}, {"text": "My doctor told me to sleep enough and drink a lot of water.", "structureVi": "tell + ai + to V: bảo ai làm gì\na lot of = plenty of", "structureEn": "tell + person + to + verb\na lot of = plenty of"}]$j$::jsonb),
