  ('advanced', 'shopping-money', 'Nhiều người tiêu dùng bị thuyết phục mua những thứ họ thật sự không cần.', $j$[{"text": "Many consumers are persuaded to buy things they don't actually need.", "structureVi": "Câu bị động: are persuaded to + V\nmệnh đề quan hệ rút gọn: things (that) they need", "structureEn": "Passive: are persuaded to + verb\na relative clause: things (that) they need"}, {"text": "Many shoppers are convinced to buy things that they do not really need.", "structureVi": "be convinced to + V\nthat-clause bổ nghĩa things", "structureEn": "be convinced to + verb\na that-clause describing things"}]$j$::jsonb),
