  ('beginner', 'entertainment-leisure', 'Chúng tôi xem phim vào tối thứ Bảy.', $j$[{"text": "We watch a movie on Saturday evening.", "structureVi": "on + thứ + buổi: on Saturday evening\nthì hiện tại đơn: thói quen", "structureEn": "on + day + part of day\npresent simple: habit"}, {"text": "We watch movies on Saturday nights.", "structureVi": "số nhiều movies: thói quen\non Saturday nights", "structureEn": "plural movies: habit\non Saturday nights"}]$j$::jsonb),
