  ('advanced', 'entertainment-leisure', 'Thời gian rảnh được dùng tốt có thể giúp con người hồi phục và sáng tạo hơn.', $j$[{"text": "Well-used free time can help people recover and become more creative.", "structureVi": "Phân từ quá khứ làm tính từ: well-used\nhelp + ai + V\nbecome + so sánh hơn", "structureEn": "A past participle as an adjective: well-used\nhelp + person + verb\nbecome + comparative"}, {"text": "Leisure time that is spent well can help people recharge and be more creative.", "structureVi": "mệnh đề quan hệ: that is spent well\nrecharge: nạp lại năng lượng", "structureEn": "a relative clause: that is spent well\nrecharge = recover"}]$j$::jsonb),
  ('beginner', 'nature-environment', 'Hôm nay trời nắng và đẹp.', $j$[{"text": "It is sunny and beautiful today.", "structureVi": "It is + tính từ thời tiết\ntoday: hôm nay", "structureEn": "It is + weather adjective\ntoday"}, {"text": "The weather is sunny and lovely today.", "structureVi": "The weather is + adj\nlovely = beautiful", "structureEn": "The weather is + adjective\nlovely = beautiful"}]$j$::jsonb),
  ('intermediate', 'nature-environment', 'Chúng ta nên giảm rác thải nhựa để bảo vệ biển.', $j$[{"text": "We should reduce plastic waste to protect the ocean.", "structureVi": "should + V: nên làm gì\nto V chỉ mục đích\nplastic waste: rác thải nhựa", "structureEn": "should + verb\nto + verb for purpose\nplastic waste"}, {"text": "We ought to cut down on plastic waste in order to protect the sea.", "structureVi": "ought to + V = should\ncut down on: giảm\nin order to + V", "structureEn": "ought to + verb = should\ncut down on = reduce\nin order to + verb"}]$j$::jsonb),
  ('advanced', 'nature-environment', 'Biến đổi khí hậu đang đe dọa nhiều loài động vật đến mức tuyệt chủng.', $j$[{"text": "Climate change is threatening many animal species with extinction.", "structureVi": "thì hiện tại tiếp diễn: is threatening\nthreaten + ai/cái gì + with + danh từ", "structureEn": "present continuous: is threatening\nthreaten + object + with + noun"}, {"text": "Climate change is putting many animal species at risk of extinction.", "structureVi": "put + ai/cái gì + at risk of + danh từ\nextinction: sự tuyệt chủng", "structureEn": "put + object + at risk of + noun\nextinction"}]$j$::jsonb),
  ('beginner', 'science-technology', 'Điện thoại của tôi hết pin.', $j$[{"text": "My phone has run out of battery.", "structureVi": "run out of + danh từ: hết\nthì hiện tại hoàn thành: has run out", "structureEn": "run out of + noun\npresent perfect: has run out"}, {"text": "My phone's battery is dead.", "structureVi": "sở hữu cách: phone's battery\ndead: hết pin", "structureEn": "possessive: phone's battery\ndead = empty"}]$j$::jsonb),
  ('intermediate', 'science-technology', 'Trí tuệ nhân tạo đang thay đổi cách chúng ta làm việc.', $j$[{"text": "Artificial intelligence is changing the way we work.", "structureVi": "thì hiện tại tiếp diễn cho thay đổi đang diễn ra\nthe way + mệnh đề", "structureEn": "present continuous for ongoing change\nthe way + clause"}, {"text": "Artificial intelligence is changing how we do our jobs.", "structureVi": "how + mệnh đề: cách mà\ndo our jobs = work", "structureEn": "how + clause\ndo our jobs = work"}]$j$::jsonb),
