  ('intermediate', 'culture-society', 'Ở nước tôi, người trẻ thường sống chung với cha mẹ cho đến khi lập gia đình.', $j$[{"text": "In my country, young people usually live with their parents until they get married.", "structureVi": "until + mệnh đề: cho đến khi\nget married: kết hôn\nlive with + ai", "structureEn": "until + clause\nget married\nlive with + person"}, {"text": "In my country, young people tend to live with their parents until they start their own families.", "structureVi": "tend to + V: có xu hướng\nstart a family: lập gia đình", "structureEn": "tend to + verb\nstart a family"}]$j$::jsonb),
  ('advanced', 'culture-society', 'Sự khác biệt giữa các thế hệ có thể là nguồn xung đột, nhưng cũng là cơ hội để học hỏi.', $j$[{"text": "Generational differences can be a source of conflict, but they are also an opportunity to learn.", "structureVi": "a source of + danh từ\nan opportunity to + V: cơ hội để làm gì\ncan be: có thể là", "structureEn": "a source of + noun\nan opportunity to + verb\ncan be"}, {"text": "Differences between generations can cause conflict, but they can also be a chance to learn from each other.", "structureVi": "cause + danh từ\na chance to + V\nlearn from each other: học hỏi lẫn nhau", "structureEn": "cause + noun\na chance to + verb\nlearn from each other"}]$j$::jsonb),
