  ('intermediate', 'history-geography', 'Sông Mê Kông chảy qua nhiều quốc gia trước khi ra biển.', $j$[{"text": "The Mekong River flows through many countries before reaching the sea.", "structureVi": "before + V-ing: trước khi\nflow through: chảy qua\nmany countries", "structureEn": "before + V-ing\nflow through\nmany countries"}, {"text": "The Mekong River passes through several countries before it reaches the sea.", "structureVi": "before + mệnh đề\npass through = flow through\nseveral + danh từ số nhiều", "structureEn": "before + clause\npass through = flow through\nseveral + plural noun"}]$j$::jsonb),
  ('advanced', 'history-geography', 'Hiểu lịch sử giúp chúng ta tránh lặp lại những sai lầm của quá khứ.', $j$[{"text": "Understanding history helps us avoid repeating the mistakes of the past.", "structureVi": "Danh động từ làm chủ ngữ\nhelp + ai + V\navoid + V-ing", "structureEn": "A gerund as the subject\nhelp + person + verb\navoid + V-ing"}, {"text": "If we understand history, we can avoid making the same mistakes as in the past.", "structureVi": "Câu điều kiện loại 1: If + hiện tại, can + V\nthe same... as...", "structureEn": "First conditional: If + present, can + verb\nthe same... as..."}]$j$::jsonb),
