  ('intermediate', 'religion-spirituality', 'Nhiều người tìm đến thiền để giảm căng thẳng và tìm sự bình yên.', $j$[{"text": "Many people turn to meditation to reduce stress and find peace.", "structureVi": "turn to + danh từ: tìm đến\nto V chỉ mục đích\nfind inner peace", "structureEn": "turn to + noun\nto + verb for purpose\nfind inner peace"}, {"text": "Many people practice meditation in order to relieve stress and find inner peace.", "structureVi": "in order to + V\nrelieve stress: giảm căng thẳng\npractice + danh từ", "structureEn": "in order to + verb\nrelieve stress\npractice + noun"}]$j$::jsonb),
  ('advanced', 'religion-spirituality', 'Tôn trọng tín ngưỡng của người khác là nền tảng của một xã hội hòa hợp.', $j$[{"text": "Respecting other people's beliefs is the foundation of a harmonious society.", "structureVi": "Danh động từ làm chủ ngữ\nsở hữu cách: other people's\nthe foundation of + danh từ", "structureEn": "A gerund as the subject\npossessive: other people's\nthe foundation of + noun"}, {"text": "Respect for the beliefs of others is the basis of a harmonious society.", "structureVi": "respect for + danh từ\nthe basis of = the foundation of", "structureEn": "respect for + noun\nthe basis of = the foundation of"}]$j$::jsonb),
