  ('advanced', 'law-justice', 'Mọi người đều bình đẳng trước pháp luật, bất kể địa vị hay tài sản.', $j$[{"text": "Everyone is equal before the law, regardless of status or wealth.", "structureVi": "equal before the law: bình đẳng trước pháp luật\nregardless of + danh từ: bất kể", "structureEn": "equal before the law\nregardless of + noun"}, {"text": "All people are equal under the law, no matter what their status or wealth is.", "structureVi": "no matter what + mệnh đề: bất kể\nunder the law = before the law", "structureEn": "no matter what + clause\nunder the law = before the law"}]$j$::jsonb),
  ('beginner', 'philosophy-ethics', 'Nói thật là việc tốt.', $j$[{"text": "Telling the truth is a good thing.", "structureVi": "Danh động từ làm chủ ngữ: Telling...\na good thing: việc tốt", "structureEn": "A gerund as the subject: Telling...\na good thing"}, {"text": "It is good to tell the truth.", "structureVi": "It is + adj + to V\ntell the truth: nói thật", "structureEn": "It is + adjective + to + verb\ntell the truth"}]$j$::jsonb),
  ('intermediate', 'philosophy-ethics', 'Có lúc chúng ta phải chọn giữa điều đúng và điều dễ dàng.', $j$[{"text": "Sometimes we have to choose between what is right and what is easy.", "structureVi": "choose between A and B: chọn giữa\nwhat + mệnh đề: điều mà\nhave to + V", "structureEn": "choose between A and B\nwhat + clause: the thing that\nhave to + verb"}, {"text": "There are times when we must choose between doing the right thing and doing the easy thing.", "structureVi": "There are times when + mệnh đề: có lúc\nbetween + V-ing and + V-ing", "structureEn": "There are times when + clause\nbetween + V-ing and + V-ing"}]$j$::jsonb),
  ('advanced', 'philosophy-ethics', 'Liệu một hành động có thể được coi là đạo đức nếu nó chỉ xuất phát từ nỗi sợ bị trừng phạt?', $j$[{"text": "Can an action be considered moral if it only stems from the fear of being punished?", "structureVi": "Câu hỏi với can + bị động: be considered\nif: nếu\nstem from: xuất phát từ\nfear of + V-ing", "structureEn": "A question with can + passive: be considered\nif\nstem from\nfear of + V-ing"}, {"text": "Is an action still moral if it comes only from fear of punishment?", "structureVi": "Is + S + still + adj?\ncome from = stem from\nfear of + danh từ", "structureEn": "Is + subject + still + adjective?\ncome from = stem from\nfear of + noun"}]$j$::jsonb)
) as v(level, category, vietnamese, answers)
join public.prompts p
  on p.writing_type = 'sentence' and p.difficulty = v.level and p.category = v.category and p.prompt_text = v.vietnamese
on conflict (prompt_id) do nothing;
